            'body'=>['تقوم فلسفة NEXVARY على أن الخطر لا يظهر دائمًا في صورة هجوم واضح. أحيانًا يكون الخطر في إعداد ضعيف، جهاز غير مؤمّن، جمع بيانات غير ضروري، بيئة حساسة لم تُفحص، أو دليل رقمي لم تتم المحافظة عليه بطريقة صحيحة. لذلك نربط بين الحماية الوقائية والوعي الفني وهندسة الخصوصية والتحقق الجنائي عندما يتطلب الحادث مراجعة تستند إلى أدلة بدل الاعتماد على الانطباع أو الإشارة المنفردة.','لا نقدم كل إشارة تقنية باعتبارها حكمًا نهائيًا. الأدوات البرمجية تساعد على الكشف والفرز والتوثيق وتحديد الأولوية، بينما بعض الحالات تحتاج فحصًا متخصصًا أو معدات ميدانية أو إجراءات رسمية لحفظ الأدلة. هذا الفصل جزء أساسي من بناء منتج أمني موثوق، ويظهر في طريقة عرض الخدمات والتطبيقات والمشروعات وحالة التوزيع وتوقعات الخصوصية عبر المنصة.'],
            'pillars'=>['Cybersecurity'=>'تقليل سطح الهجوم وتقوية الأنظمة قبل وقوع الحوادث.','Counter-Surveillance'=>'فحص تقني ووعي للبيئات التي تكون فيها السرية عاملًا أساسيًا.','Digital Forensics'=>'تحقيق منظم وحفظ أدلة بمسارات قابلة للتكرار والمراجعة.','Privacy Technology'=>'أدوات وهندسة تقلل التعرض غير الضروري للبيانات منذ التصميم.'],'channels'=>'روابط NEXVARY الرسمية',
        ],
        'contact'=>[
            'title'=>'تواصل مع NEXVARY للأمن التقني','description'=>'تواصل مع NEXVARY بخصوص الأمن السيبراني ومكافحة التجسس الفني والتحليل الجنائي الرقمي وتقنيات الخصوصية والشراكات والدعم.','h1'=>'أخبرنا كيف يمكننا مساعدتك.','lead'=>'أرسل تفاصيل واضحة عن سبب التواصل دون مشاركة كلمات مرور أو مفاتيح سرية أو بيانات دفع.','success'=>'تم استلام طلبك بنجاح. شكرًا لتواصلك معنا.','send'=>'إرسال الطلب','fields'=>['name'=>'الاسم الكامل *','email'=>'البريد الإلكتروني *','phone'=>'رقم الهاتف','company'=>'الشركة / الجهة','country'=>'الدولة','reason'=>'سبب التواصل *','preferred'=>'طريقة التواصل المفضلة *','message'=>'رسالتك *'],'reasons'=>['general'=>'استفسار عام','cybersecurity'=>'الأمن السيبراني','tscm'=>'مكافحة التجسس الفني TSCM','forensics'=>'التحليل الجنائي الرقمي','privacy'=>'تقنيات الخصوصية','partnership'=>'شراكة أو تعاون','support'=>'دعم فني','other'=>'سبب آخر'],'phone_call'=>'اتصال هاتفي',
            'body'=>['استخدم هذه الصفحة لطلب معلومات عن خدمة أمنية أو مشروع تقني أو شراكة أو دعم مرتبط بمنتجات NEXVARY. كلما كان الوصف محددًا، كان من الأسهل توجيه الطلب إلى المسار المناسب. لا ترسل كلمات مرور أو رموز تحقق أو مفاتيح API أو بيانات بطاقات أو نسخًا من مواد شديدة الحساسية داخل النموذج العام، لأن قناة التواصل الأولى يجب أن تحتوي فقط على المعلومات اللازمة لفهم طبيعة الطلب.','في الطلبات المتعلقة بحادث أمني أو دليل رقمي، اذكر نوع البيئة والمشكلة العامة أولًا حتى يتم تحديد قناة مناسبة قبل تبادل التفاصيل الحساسة. وفي طلبات مكافحة التجسس الفني، اذكر نوع المكتب أو الغرفة أو المركبة أو مجموعة الأجهزة أو بيئة الترددات المطلوب تقييمها دون كشف معلومات تشغيلية لا لزوم لها في المرحلة الأولى.'],
        ],
        'work'=>[
            'title'=>'أعمال ومشاريع NEXVARY','description'=>'استعرض المشاريع والتطبيقات المنشورة من NEXVARY وحالة توفر كل مشروع للتنزيل أو العرض أو الطلب أو الاستخدام الداخلي.','h1'=>'مشاريع منشورة بحالة توفر واضحة','lead'=>'كل مشروع منشور يوضح حالته بدل إظهار زر تنزيل غير متاح أو رابط ميت.','empty_title'=>'لا توجد مشاريع منشورة حاليًا','empty_text'=>'سيظهر هنا كل مشروع بعد اجتياز بوابة الإصدار وتحديد سياسة التوزيع.','view'=>'عرض المشروع','all'=>'كل المشاريع','ask'=>'استفسر عن المشروع','download'=>'تنزيل الإصدار','request'=>'طلب الوصول','features'=>'القدرات الرئيسية','screens'=>'صور المشروع',
            'body'=>['صفحة أعمالنا ليست متجر تنزيلات تلقائيًا. بعض المشاريع مخصصة للعرض، وبعضها متاح حسب الطلب، وبعضها للاستخدام الداخلي أو ما زال في مرحلة قادمة. عندما يكون التنزيل عامًا فعلًا يظهر ذلك بوضوح داخل صفحة المشروع. هذا الأسلوب يحافظ على دقة حالة التوفر ويمنع الأزرار التي تقود إلى ملفات مفقودة أو صفحات غير متاحة أو إصدارات غير واضحة المصدر.','يساعد الهيكل نفسه محركات البحث على فهم العلاقة بين فهرس المشاريع وصفحة كل مشروع منشور. تربط الروابط الداخلية الكتالوج بالسجلات الفردية، بينما تقتصر خريطة الموقع على الأسطح المقصودة للاكتشاف العام. ويمكن لمن يحتاج مشروعًا متاحًا حسب الطلب استخدام صفحة التواصل بدل الوصول إلى مسار تنزيل ميت أو غير مصرح به.'],
            'show_body'=>['تعرض هذه الصفحة المعلومات المنشورة رسميًا عن المشروع وحالة توفره الحالية. قد يكون المشروع متاحًا للتنزيل، مخصصًا للعرض، متاحًا حسب الطلب، للاستخدام الداخلي، أو في مرحلة قادمة. لا يظهر زر تنزيل عام إلا عندما تسمح سياسة التوزيع بذلك صراحة ويكون ملف الإصدار مهيأً للتسليم العام.','تساعد معلومات المنصة والإصدار والقدرات وحالة التوفر على التحقق من هوية المشروع وطريقة توزيعه المقصودة قبل الاستخدام. وعندما يتضمن الإصدار العام معلومات سلامة، يُفضّل التحقق من رقم الإصدار والبصمة المنشورة إن وجدت. أما المشاريع الداخلية أو المقيدة فلا ينبغي الحصول عليها من مرايا غير رسمية أو نسخ معاد توزيعها خارج قناة NEXVARY المحكومة.'],'availability'=>'حالة التوفر المعروضة هنا هي الحالة الرسمية الحالية لهذا المشروع.',
        ],
    ],

    'tr' => [
        'name'=>'Türkçe','dir'=>'ltr','og_locale'=>'tr_TR','nav'=>['home'=>'Ana Sayfa','services'=>'Hizmetler','work'=>'Projelerimiz','apps'=>'Uygulamalar','about'=>'Hakkımızda','contact'=>'İletişim','back'=>'Geri'],'tagline'=>'Görünmeyenin ötesinde güvenlik.',
        'home'=>['title'=>'NEXVARY — Görünmeyenin Ötesinde Güvenlik','description'=>'NEXVARY; siber güvenlik, teknik karşı gözetim, dijital adli bilişim ve gizlilik teknolojilerini çok katmanlı bir güvenlik platformunda birleştirir.','h1'=>'Görünmeyenin Ötesinde Güvenlik.','lead'=>'Karşı gözetim, siber güvenlik, dijital adli bilişim ve gizlilik teknolojilerini tek korumalı deneyimde birleştiren gelişmiş güvenlik platformu.','section'=>'Çok katmanlı güvenlik yeteneği','body'=>['NEXVARY, çoğu kurumda ayrı ayrı yönetilen güvenlik katmanlarını birbirine bağlar: uç nokta ve ağ savunması, teknik maruziyetin azaltılması, karşı gözetim farkındalığı, gizlilik mühendisliği ve delillerin korunması gerektiğinde dijital adli bilişim iş akışları. Amaç yalnızca daha fazla araç sunmak değildir. Saldırı yüzeyini azaltmaktan doğrulama ve incelemeye, oradan da operasyonel kararı destekleyebilecek raporlamaya uzanan anlaşılır ve tekrar edilebilir bir süreç oluşturmaktır.','Platform; farkındalık özellikleri, savunma yazılımları ve profesyonel doğrulama gerektiren çalışmalar arasında bilinçli bir ayrım yapar. Ziyaretçiler güvenlik hizmetlerini inceleyebilir, gizlilik odaklı uygulamaları keşfedebilir, Projelerimiz bölümündeki yayımlanmış çalışmaları görebilir veya belirli bir teknik ihtiyaç için NEXVARY ile iletişime geçebilir. Temel içerik, gezinme, meta veriler ve yapılandırılmış bilgiler JavaScript çalışmadan önce sunucu tarafından gönderildiği için arama tarayıcıları da siteyi doğru biçimde okuyabilir.'],'capabilities'=>['TSCM'=>'Hassas ortamlar için RF farkındalığı ve teknik karşı gözetim operasyonları.','Cybersecurity'=>'Sistem güçlendirme, saldırı yüzeyi azaltma, değerlendirme ve olay müdahalesi.','SafeScan'=>'Veri minimizasyonuna dayalı, tarayıcı içinde sıfır depolamalı dosya incelemesi.','Audio Shield'=>'Ses gizliliği, maruziyet farkındalığı ve savunma iş akışları.','Tower Guard'=>'Profesyonel doğrulama sınırları açık biçimde belirtilen hücresel anomali farkındalığı.','Digital Forensics'=>'Yapılandırılmış delil yönetimi, inceleme ve tekrarlanabilir raporlama süreçleri.']],
        'services'=>['title'=>'NEXVARY Güvenlik Hizmetleri','description'=>'NEXVARY hizmetleri TSCM, siber güvenlik, gizlilik, dijital adli bilişim, fiziksel güvenlik teknolojileri ve güvenlik istihbaratını kapsar.','h1'=>'Çok disiplinli teknik koruma','lead'=>'Dijital ve fiziksel maruziyeti azaltmak için farkındalık, teknik inceleme ve profesyonel doğrulamayı açıkça ayıran hizmetler.','body'=>['NEXVARY hizmetleri, risk bir olaya dönüşmeden önce onu azaltma ilkesi etrafında tasarlanır. Çalışma; ortamın, kritik varlıkların ve olası maruziyet noktalarının anlaşılmasıyla başlar. Ağlar, uç cihazlar, kablosuz iletişim, fiziksel alanlar ve operasyonel süreçler birlikte değerlendirilir. Farkındalık araçları ile uzman denetimi birbirine karıştırılmaz; böylece müşteriler bir yazılım sinyalinin ne anlama geldiğini ve ne zaman saha incelemesi ya da resmi delil yönetimi gerektiğini anlayabilir.','Siber güvenlik çalışmaları saldırı yüzeyini azaltma, yapılandırma güçlendirme, zafiyet inceleme, olay müdahalesi ve mimariye odaklanır. Teknik karşı gözetim; hassas ortamları, radyo frekansı farkındalığını ve sistematik teknik incelemeyi ele alır. Dijital adli bilişim, delilin korunmasına, tekrarlanabilir analize ve savunulabilir raporlamaya önem verir. Fiziksel güvenlik teknolojileri ise kameraları, geçiş kontrolünü, alarm sistemlerini, güvenli ağları ve sensörleri tek koordineli koruma katmanında bir araya getirir.'],'cards'=>['TSCM & Counter-Surveillance'=>'Ofis, araç, oda, cihaz, ağ ve RF ortamları için teknik incelemeler.','Cybersecurity'=>'Değerlendirme, güçlendirme, zafiyet azaltma, olay müdahalesi ve güvenlik mimarisi.','Digital Privacy'=>'Hassas kullanıcı ve ekipler için gizlilik odaklı süreçler ve maruziyet azaltma.','Digital Forensics'=>'Yapılandırılmış delil inceleme, soruşturma iş akışları ve savunulabilir raporlama.','Physical Security Technology'=>'CCTV, geçiş kontrolü, alarmlar, güvenli ağlar ve sensör entegrasyonu.','Security Intelligence'=>'Karar desteği için tehdit, ihlal ve yapay zekâ güvenliği istihbaratı.']],
        'apps'=>['title'=>'NEXVARY Güvenlik Uygulamaları','description'=>'Gizlilik, sıfır depolamalı inceleme, tehdit istihbaratı, hücresel farkındalık ve dijital adli bilişim için NEXVARY uygulamalarını keşfedin.','h1'=>'Tek platformda güvenlik uygulamaları','lead'=>'Yararlı sinyaller, açık iş akışları ve kontrollü sürümler sunmak için tasarlanmış savunma ve gizlilik odaklı uygulamalar.','body'=>['NEXVARY uygulama ekosistemi; gizlilik araçlarının, inceleme yardımcılarının, istihbarat yüzeylerinin ve adli bilişim süreçlerinin birbirine karışmaması için yapılandırılmıştır. Bazı araçlar gereksiz veri aktarımını azaltmak amacıyla doğrudan tarayıcıda çalışır. Bazıları ise uzman doğrulamasına geçmeden önce operatörün bir sinyali anlamasına yardımcı olan analiz ve farkındalık sağlar. Her uygulama ne yaptığını, hangi verilerle çalıştığını ve teknik sınırlarını açıkça belirtmek zorundadır.','SafeScan, birincil incelemeyi tarayıcıda tutarak sıfır depolama yaklaşımını gösterir. Diğer ürünler hücresel farkındalık, ses gizliliği, güvenlik istihbaratı veya tekrarlanabilir DFIR süreçlerine odaklanır. Yayımlanmış projeler ve erişilebilirlik durumları Projelerimiz bölümünde incelenebilir. İndirme seçeneği yalnızca proje açıkça dağıtıma açıldığında ve ilgili ürün için gerekli sürüm kapısından geçtiğinde görünür.'],'cards'=>['Audio Shield'=>'Ses gizliliği ve teknik maruziyet farkındalığı için savunma araçları.','Tower Guard'=>'Profesyonel doğrulama rehberliğiyle hücresel anomali farkındalığı.','SafeScan'=>'İsteğe bağlı hash itibarıyla tarayıcı içi sıfır depolamalı statik inceleme.','Threat Intelligence'=>'Savunma kararlarını destekleyen seçilmiş güvenlik istihbaratı.','AI Intelligence'=>'Yapay zekâ güvenliği ve yeni teknolojilere odaklı istihbarat.','DFIR Lab'=>'Yapılandırılmış dijital adli bilişim ve soruşturma desteği.'],'open'=>'SafeScan’i Aç'],
        'safescan'=>['title'=>'SafeScan Sıfır Depolamalı Dosya İncelemesi','description'=>'SafeScan, dosya içeriğini NEXVARY sunucularına yüklemeden tarayıcı içinde birincil inceleme yapar ve isteğe bağlı SHA-256 itibar sorgusu sunar.','h1'=>'SafeScan','lead'=>'Birincil inceleme tarayıcıda çalışır. Dosya içeriği NEXVARY sunucusuna yüklenmez; isteğe bağlı itibar sorgusunda yalnızca SHA-256 özeti kullanılabilir.','section'=>'Dosyanıza ne olur?','steps'=>[['Yerel okuma','Tarayıcı, temel inceleme için dosya özelliklerini yerel olarak okur.'],['SHA-256','Dosya içeriği gönderilmeden kriptografik bir parmak izi hesaplanabilir.'],['İsteğe bağlı sorgu','İtibar sorgusu etkinse yalnızca hash değeri itibar hizmetine gönderilir.']],'body'=>['SafeScan veri minimizasyonu ilkesiyle tasarlanmıştır. Basit özellikleri görmek için dosyanın tamamını merkezi bir sunucuya yüklemek yerine, platformun izin verdiği ölçüde birincil analiz tarayıcı içinde gerçekleştirilir. Bu yaklaşım gereksiz maruziyeti azaltır ve kullanıcıya hangi verinin cihazda kaldığı, hangi teknik bilginin dış bir itibar hizmetiyle paylaşılabileceği konusunda daha açık bir görünüm sağlar. Tarayıcıdaki ilk sinyal, resmi kötü amaçlı yazılım analizi veya adli bilişim sonucu olarak sunulmaz.','İtibar sorgusu kullanıldığında SafeScan bir SHA-256 parmak izi hesaplayabilir ve özgün dosya içeriğini göndermeden bu özeti teknik tanımlayıcı olarak kullanabilir. İtibar sonucu bir dosyanın kesin biçimde güvenli veya zararlı olduğunu kanıtlamaz; yalnızca bağlamla birlikte yorumlanması gereken ek bir sinyaldir. Hassas materyaller, olay müdahale delilleri veya adli vakalar daha sıkı koruma, delil zinciri ve uzman doğrulaması gerektirir.']],
        'about'=>['title'=>'NEXVARY Güvenlik Teknolojisi Hakkında','description'=>'NEXVARY’nin siber güvenlik, teknik karşı gözetim, dijital adli bilişim, gizlilik teknolojileri ve katmanlı koruma yaklaşımını öğrenin.','h1'=>'İlk bakışta görünmeyen riskler için güvenlik teknolojisi.','lead'=>'NEXVARY; siber güvenliği, teknik karşı gözetimi, dijital adli bilişimi ve gizlilik teknolojisini bağlantılı koruma katmanlarında birleştirir.','body'=>['NEXVARY, güvenlik riskinin her zaman açık bir saldırı biçiminde görünmediği düşüncesiyle hareket eder. Risk; zayıf bir yapılandırmada, yönetilmeyen bir cihazda, gereksiz veri toplamanda, teknik olarak incelenmemiş hassas bir ortamda veya doğru korunmamış dijital delilde bulunabilir. Bu nedenle platform önleyici korumayı, teknik farkındalığı, gizlilik mühendisliğini ve bir olay delile dayalı inceleme gerektirdiğinde adli doğrulamayı birbirine bağlar.','Yazılım sinyalleri kesin hüküm gibi sunulmaz. Savunma uygulamaları sorunları tespit etmeye, sınıflandırmaya, belgelemeye ve önceliklendirmeye yardımcı olabilir; bazı durumlarda ise uzman saha incelemesi, özel ekipman veya resmi delil yönetimi gerekir. Bu ayrım NEXVARY ürün modelinin temelidir ve hizmetlerin, uygulamaların, yayımlanmış projelerin, dağıtım durumunun ve gizlilik beklentilerinin nasıl sunulduğuna doğrudan yansır.'],'pillars'=>['Cybersecurity'=>'Olay oluşmadan önce saldırı yüzeyini azaltma ve sistemleri güçlendirme.','Counter-Surveillance'=>'Gizliliğin kritik olduğu ortamlar için teknik inceleme ve farkındalık.','Digital Forensics'=>'Tekrarlanabilir süreçlerle yapılandırılmış inceleme ve delil yönetimi.','Privacy Technology'=>'Gereksiz veri maruziyetini tasarımdan itibaren azaltan araçlar ve mimari.'],'channels'=>'Resmî NEXVARY kanalları'],
        'contact'=>['title'=>'NEXVARY Güvenlik Ekibiyle İletişim','description'=>'Siber güvenlik, teknik karşı gözetim, dijital adli bilişim, gizlilik teknolojileri, ortaklıklar ve teknik destek için NEXVARY ile iletişime geçin.','h1'=>'Size nasıl yardımcı olabileceğimizi anlatın.','lead'=>'Parola, gizli anahtar veya ödeme bilgisi paylaşmadan talebinizi açık biçimde açıklayın.','success'=>'Talebiniz başarıyla alındı. NEXVARY ile iletişim kurduğunuz için teşekkür ederiz.','send'=>'Talebi gönder','fields'=>['name'=>'Ad soyad *','email'=>'E-posta *','phone'=>'Telefon','company'=>'Şirket / Kurum','country'=>'Ülke','reason'=>'İletişim nedeni *','preferred'=>'Tercih edilen iletişim yöntemi *','message'=>'Mesajınız *'],'reasons'=>['general'=>'Genel bilgi','cybersecurity'=>'Siber güvenlik','tscm'=>'Karşı gözetim / TSCM','forensics'=>'Dijital adli bilişim','privacy'=>'Gizlilik teknolojisi','partnership'=>'Ortaklık','support'=>'Destek','other'=>'Diğer'],'phone_call'=>'Telefon görüşmesi','body'=>['Bu sayfayı bir güvenlik hizmeti, teknik proje, ortaklık veya NEXVARY ürünleriyle ilgili destek talebi için kullanabilirsiniz. Açık ve belirli bir açıklama talebin doğru iş akışına yönlendirilmesini kolaylaştırır. Genel iletişim formuna parola, tek kullanımlık kod, API sırrı, ödeme kartı bilgisi veya yüksek hassasiyetli materyalin kopyasını göndermeyin; ilk temas yalnızca talebin niteliğini anlamak için gerekli bilgileri içermelidir.','Aktif bir güvenlik olayı veya dijital delil konusu için önce ortamı ve genel problemi açıklayın; hassas ayrıntılar uygun bir kanal belirlendikten sonra paylaşılmalıdır. Teknik karşı gözetim taleplerinde değerlendirilecek ofis, oda, araç, cihaz grubu veya RF ortamının türünü belirtin, ancak ilk aşamada gereksiz operasyonel bilgileri açıklamayın.'],'work'=>[]],
        'work'=>['title'=>'NEXVARY Projeleri ve Çalışmalarımız','description'=>'Yayımlanmış NEXVARY projelerini ve uygulamalarını; indirme, vitrin, talep, kurum içi kullanım veya yakında durumlarıyla birlikte inceleyin.','h1'=>'Erişilebilirliği açıkça belirtilen yayımlanmış projeler','lead'=>'Her proje, kullanılamayan indirme düğmeleri veya ölü bağlantılar yerine mevcut dağıtım durumunu açıkça gösterir.','empty_title'=>'Henüz yayımlanmış proje yok','empty_text'=>'Projeler sürüm kapısını geçtikten ve açık bir dağıtım politikası aldıktan sonra burada görünür.','view'=>'Projeyi görüntüle','all'=>'Tüm projeler','ask'=>'Bu proje hakkında sor','download'=>'Sürümü indir','request'=>'Erişim talep et','features'=>'Temel yetenekler','screens'=>'Proje ekran görüntüleri','body'=>['Projelerimiz bölümü otomatik bir indirme mağazası değildir. Bazı çalışmalar vitrin amacıyla yayımlanır, bazıları yalnızca talep üzerine sunulur, bazıları kurum içi kalır ve bazıları yakında olarak listelenebilir. Yalnızca dağıtım politikası açıkça izin verdiğinde halka açık indirme gösterilir. Bu yaklaşım erişilebilirlik bilgisini doğru tutar ve eksik dosyalara, erişilemeyen sayfalara veya belirsiz sürüm durumlarına yönlendiren düğmeleri engeller.','Aynı yapı arama tarayıcılarının katalog ile her yayımlanmış proje sayfası arasındaki ilişkiyi anlamasına yardımcı olur. İç bağlantılar katalogdan proje kayıtlarına gider; site haritası ise yalnızca kamusal keşif için tasarlanan yüzeyleri içerir. Talep üzerine sunulan bir projeye ihtiyaç duyan ziyaretçiler, ölü veya yetkisiz bir indirme yoluna gitmek yerine iletişim sayfasını kullanabilir.'],'show_body'=>['Bu sayfa projenin resmî olarak yayımlanan bilgilerini ve güncel erişilebilirlik durumunu gösterir. Proje halka açık indirilebilir, vitrin, talep üzerine, kurum içi veya yakında durumunda olabilir. Halka açık indirme yalnızca dağıtım politikası izin verdiğinde ve bir sürüm dosyası açıkça yapılandırıldığında sunulur.','Platform, sürüm, yetenekler ve erişilebilirlik bilgileri projenin kimliğini ve amaçlanan dağıtım biçimini doğrulamaya yardımcı olur. Genel sürüm bütünlük bilgisi içeriyorsa yayımlanan sürüm ve sağlama toplamı kontrol edilmelidir. Kurum içi veya kısıtlı projeler resmî olmayan aynalardan ya da kontrol dışı yeniden dağıtılmış kopyalardan edinilmemelidir.'],'availability'=>'Burada gösterilen erişilebilirlik bu projenin güncel resmî dağıtım durumudur.'],
    ],

    'ru' => [
        'name'=>'Русский','dir'=>'ltr','og_locale'=>'ru_RU','nav'=>['home'=>'Главная','services'=>'Услуги','work'=>'Наши проекты','apps'=>'Приложения','about'=>'О нас','contact'=>'Контакты','back'=>'Назад'],'tagline'=>'Безопасность за пределами видимого.',
        'home'=>['title'=>'NEXVARY — Безопасность за Пределами Видимого','description'=>'NEXVARY объединяет кибербезопасность, техническое противодействие наблюдению, цифровую криминалистику и технологии приватности.','h1'=>'Безопасность за пределами видимого.','lead'=>'Защищённая платформа, объединяющая противодействие наблюдению, кибербезопасность, цифровую криминалистику и технологии приватности.','section'=>'Многоуровневая система безопасности','body'=>['NEXVARY связывает уровни защиты, которые часто управляются отдельно: безопасность конечных устройств и сетей, снижение технической экспозиции, осведомлённость о рисках наблюдения, инженерия приватности и цифровая криминалистика, когда необходимо сохранить и исследовать доказательства. Цель состоит не в простом увеличении количества инструментов, а в создании понятного процесса от уменьшения поверхности атаки через проверку и расследование до отчётности, способной поддержать обоснованное операционное решение.','Платформа намеренно разделяет функции осведомлённости, защитное программное обеспечение и работы, требующие профессиональной проверки. Посетители могут изучить услуги безопасности, приложения с приоритетом приватности, опубликованные проекты в разделе «Наши проекты» или обратиться в NEXVARY с конкретной технической задачей. Основной контент, навигация, метаданные и структурированная информация формируются сервером, поэтому поисковые роботы получают полноценную страницу ещё до выполнения JavaScript.'],'capabilities'=>['TSCM'=>'RF-осведомлённость и техническое противодействие наблюдению в чувствительных средах.','Cybersecurity'=>'Укрепление систем, снижение поверхности атаки, оценка и реагирование на инциденты.','SafeScan'=>'Проверка файлов в браузере без хранения содержимого и с минимизацией данных.','Audio Shield'=>'Защита приватности аудио, оценка экспозиции и защитные рабочие процессы.','Tower Guard'=>'Осведомлённость о сотовых аномалиях с чёткими границами профессиональной проверки.','Digital Forensics'=>'Структурированное обращение с доказательствами, расследование и воспроизводимая отчётность.']],
        'services'=>['title'=>'Услуги Безопасности NEXVARY','description'=>'Услуги NEXVARY охватывают TSCM, кибербезопасность, приватность, цифровую криминалистику, физическую защиту и аналитическую поддержку.','h1'=>'Многопрофильная техническая защита','lead'=>'Услуги для снижения цифровой и физической экспозиции с чётким разделением осведомлённости, технической проверки и профессиональной валидации.','body'=>['Услуги NEXVARY строятся вокруг снижения риска до того, как он превратится в инцидент. Работа начинается с понимания среды и критичных активов, после чего оценивается возможная экспозиция в сетях, конечных устройствах, беспроводной связи, физических помещениях и операционных процессах. Инструменты осведомлённости не смешиваются с профессиональной проверкой: клиент должен понимать, что означает программный сигнал и когда требуется специализированный осмотр или формальное обращение с доказательствами.','Работы по кибербезопасности сосредоточены на уменьшении поверхности атаки, укреплении конфигураций, анализе уязвимостей, реагировании на инциденты и архитектуре. Техническое противодействие наблюдению охватывает чувствительные среды, RF-осведомлённость и систематическую проверку. Цифровая криминалистика делает акцент на сохранении доказательств, воспроизводимом анализе и защищаемой отчётности. Физическая безопасность объединяет камеры, контроль доступа, сигнализацию, защищённые сети и датчики в согласованный слой.'],'cards'=>['TSCM & Counter-Surveillance'=>'Технические проверки офисов, автомобилей, помещений, устройств, сетей и RF-сред.','Cybersecurity'=>'Оценка, укрепление, снижение уязвимостей, реагирование на инциденты и архитектура безопасности.','Digital Privacy'=>'Рабочие процессы с приоритетом приватности и снижение лишней экспозиции данных.','Digital Forensics'=>'Структурированный анализ доказательств, расследования и защищаемая отчётность.','Physical Security Technology'=>'CCTV, контроль доступа, сигнализация, защищённые сети и интеграция датчиков.','Security Intelligence'=>'Отобранная аналитика угроз, утечек и безопасности ИИ для поддержки решений.']],
        'apps'=>['title'=>'Приложения Безопасности NEXVARY','description'=>'Приложения NEXVARY для приватности, проверки без хранения, аналитики угроз, сотовой осведомлённости и цифровой криминалистики.','h1'=>'Приложения безопасности на одной платформе','lead'=>'Защитные приложения с приоритетом приватности, понятными сигналами, рабочими процессами и контролируемыми выпусками.','body'=>['Экосистема приложений NEXVARY устроена так, чтобы инструменты приватности, средства проверки, аналитические поверхности и криминалистические процессы не смешивались друг с другом. Часть инструментов работает локально в браузере, уменьшая ненужную передачу данных. Другие дают анализ и контекст, позволяющий оператору понять сигнал до обращения за профессиональной проверкой. Каждое приложение должно ясно сообщать, что оно делает, какие данные обрабатывает и где находятся его технические ограничения.','SafeScan демонстрирует подход без хранения, оставляя первичную проверку в браузере. Другие продукты ориентированы на сотовую осведомлённость, приватность аудио, аналитику безопасности и воспроизводимые DFIR-процессы. Опубликованные проекты и их статус доступны в разделе «Наши проекты». Загрузка появляется только тогда, когда проект явно разрешён к распространению и прошёл соответствующую процедуру выпуска.'],'cards'=>['Audio Shield'=>'Защита приватности аудио и осведомлённость о технической экспозиции.','Tower Guard'=>'Осведомлённость о сотовых аномалиях с рекомендациями по профессиональной проверке.','SafeScan'=>'Статическая проверка в браузере без хранения с опциональной репутацией хеша.','Threat Intelligence'=>'Отобранная аналитика безопасности и рекомендации для защитных решений.','AI Intelligence'=>'Фокус на безопасности ИИ, новых технологиях и связанных рисках.','DFIR Lab'=>'Структурированные процессы цифровой криминалистики и поддержка расследований.'],'open'=>'Открыть SafeScan'],
        'safescan'=>['title'=>'SafeScan — Проверка Файлов Без Хранения','description'=>'SafeScan выполняет первичную проверку в браузере без загрузки содержимого файла в NEXVARY и поддерживает опциональную проверку репутации SHA-256.','h1'=>'SafeScan','lead'=>'Первичная проверка выполняется в браузере. Содержимое файла не загружается на сервер NEXVARY; для опциональной репутации может использоваться только SHA-256.','section'=>'Что происходит с вашим файлом?','steps'=>[['Локальное чтение','Браузер локально читает характеристики файла для первичной проверки.'],['SHA-256','Криптографический отпечаток вычисляется без отправки содержимого файла.'],['Опциональная проверка','Если проверка репутации включена, сервису передаётся только хеш.']],'body'=>['SafeScan проектируется вокруг принципа минимизации данных. Вместо загрузки полного файла на центральный сервер ради базовых характеристик первичный анализ выполняется внутри браузера в пределах возможностей платформы. Такой подход уменьшает ненужную экспозицию и позволяет пользователю лучше понимать, какие данные остаются на устройстве и какая техническая информация может быть передана внешнему сервису репутации. Первичный браузерный сигнал намеренно не выдаётся за формальное заключение о вредоносности или цифровой криминалистике.','При использовании проверки репутации SafeScan вычисляет SHA-256 и может использовать этот отпечаток как технический идентификатор без передачи исходного содержимого файла. Результат репутации является дополнительным сигналом, а не гарантией безопасности или вредоносности. Чувствительные материалы, доказательства инцидента и криминалистические случаи требуют более строгого обращения, сохранения цепочки доказательств и профессиональной проверки за пределами предварительного браузерного анализа.']],
        'about'=>['title'=>'О Технологиях Безопасности NEXVARY','description'=>'Узнайте о подходе NEXVARY к кибербезопасности, техническому противодействию наблюдению, цифровой криминалистике и технологиям приватности.','h1'=>'Технологии безопасности для рисков, которые не видны сразу.','lead'=>'NEXVARY объединяет кибербезопасность, техническое противодействие наблюдению, цифровую криминалистику и приватность в связанные уровни защиты.','body'=>['NEXVARY исходит из того, что риск безопасности не всегда выглядит как очевидная атака. Экспозиция может скрываться в слабой конфигурации, неуправляемом устройстве, избыточном сборе данных, чувствительной среде без технической проверки или цифровых доказательствах, сохранённых неправильно. Поэтому платформа соединяет профилактическую защиту, техническую осведомлённость, инженерию приватности и криминалистическую валидацию, когда инцидент требует анализа, основанного на доказательствах.','Программные сигналы не выдаются за абсолютные выводы. Защитные приложения помогают обнаруживать, классифицировать, документировать и приоритизировать проблемы, но некоторые ситуации требуют специализированного осмотра, полевого оборудования или формальных процедур обращения с доказательствами. Такое разделение является частью продуктовой модели NEXVARY и отражается в представлении услуг, приложений, проектов, статусов распространения и ожиданий приватности.'],'pillars'=>['Cybersecurity'=>'Снижение поверхности атаки и укрепление систем до возникновения инцидентов.','Counter-Surveillance'=>'Техническая проверка и осведомлённость для сред, где конфиденциальность критична.','Digital Forensics'=>'Структурированное расследование и обращение с доказательствами в воспроизводимых процессах.','Privacy Technology'=>'Инструменты и архитектура, минимизирующие ненужную экспозицию данных.'],'channels'=>'Официальные каналы NEXVARY'],
        'contact'=>['title'=>'Связаться с Командой NEXVARY','description'=>'Свяжитесь с NEXVARY по вопросам кибербезопасности, TSCM, цифровой криминалистики, приватности, партнёрства и технической поддержки.','h1'=>'Расскажите, чем мы можем помочь.','lead'=>'Опишите запрос ясно, не передавая пароли, секретные ключи или платёжные данные.','success'=>'Ваш запрос успешно получен. Благодарим за обращение в NEXVARY.','send'=>'Отправить запрос','fields'=>['name'=>'Полное имя *','email'=>'Электронная почта *','phone'=>'Телефон','company'=>'Компания / Организация','country'=>'Страна','reason'=>'Причина обращения *','preferred'=>'Предпочтительный способ связи *','message'=>'Ваше сообщение *'],'reasons'=>['general'=>'Общий вопрос','cybersecurity'=>'Кибербезопасность','tscm'=>'Противодействие наблюдению / TSCM','forensics'=>'Цифровая криминалистика','privacy'=>'Технологии приватности','partnership'=>'Партнёрство','support'=>'Поддержка','other'=>'Другое'],'phone_call'=>'Телефонный звонок','body'=>['Используйте эту страницу для вопросов об услуге безопасности, техническом проекте, партнёрстве или поддержке продуктов NEXVARY. Чем точнее описание, тем проще направить запрос в правильный процесс. Не отправляйте через публичную форму пароли, одноразовые коды, API-секреты, данные банковских карт или копии особо чувствительных материалов. Первичное сообщение должно содержать только информацию, необходимую для понимания характера задачи.','При активном инциденте или вопросе цифровых доказательств сначала опишите общую среду и проблему, чтобы определить подходящий защищённый канал до обмена чувствительными деталями. Для TSCM-запросов укажите тип офиса, помещения, автомобиля, набора устройств или RF-среды, которую требуется оценить, не раскрывая лишнюю операционную информацию на первом этапе.']],
        'work'=>['title'=>'Проекты и Работы NEXVARY','description'=>'Просматривайте опубликованные проекты NEXVARY с понятным статусом: загрузка, витрина, по запросу, внутреннее использование или скоро.','h1'=>'Опубликованные проекты с понятным статусом доступности','lead'=>'Каждый проект показывает реальный статус вместо недоступных загрузок и неработающих действий.','empty_title'=>'Опубликованных проектов пока нет','empty_text'=>'Проекты появятся здесь после прохождения выпуска и назначения явной политики распространения.','view'=>'Открыть проект','all'=>'Все проекты','ask'=>'Спросить о проекте','download'=>'Скачать выпуск','request'=>'Запросить доступ','features'=>'Ключевые возможности','screens'=>'Снимки проекта','body'=>['Раздел «Наши проекты» не является автоматическим магазином загрузок. Одни проекты публикуются как витрина, другие доступны только по запросу, часть остаётся внутренней, а некоторые могут иметь статус «скоро». Публичная загрузка появляется только при явном разрешении политики распространения. Такой подход сохраняет точность статуса и предотвращает кнопки, ведущие к отсутствующим файлам, закрытым страницам или неоднозначным версиям.','Та же структура помогает поисковым роботам понимать связь между каталогом и каждой опубликованной страницей проекта. Внутренние ссылки соединяют каталог с отдельными записями, а карта сайта включает только поверхности, предназначенные для публичного обнаружения. Для проекта «по запросу» посетитель может использовать страницу контактов вместо неработающего или неразрешённого пути загрузки.'],'show_body'=>['На этой странице представлены официально опубликованные сведения о проекте и его текущий статус. Проект может быть доступен для публичной загрузки, представлен как витрина, выдаваться по запросу, быть внутренним или находиться в статусе «скоро». Публичная загрузка показывается только при явном разрешении политики и наличии настроенного файла выпуска.','Платформа, версия, возможности и статус помогают проверить идентичность проекта и предполагаемый способ распространения. Если публичный выпуск содержит данные целостности, следует сверить опубликованную версию и контрольную сумму. Внутренние или ограниченные проекты не должны получаться с неофициальных зеркал или из перераспределённых копий вне контролируемого канала NEXVARY.'],'availability'=>'Показанный здесь статус является текущим официальным статусом распространения проекта.'],
    ],

    'de' => [
        'name'=>'Deutsch','dir'=>'ltr','og_locale'=>'de_DE','nav'=>['home'=>'Startseite','services'=>'Dienste','work'=>'Projekte','apps'=>'Anwendungen','about'=>'Über uns','contact'=>'Kontakt','back'=>'Zurück'],'tagline'=>'Sicherheit jenseits des Sichtbaren.',
        'home'=>['title'=>'NEXVARY — Sicherheit Jenseits des Sichtbaren','description'=>'NEXVARY verbindet Cybersicherheit, technische Gegenüberwachung, digitale Forensik und Datenschutztechnologie in einer mehrschichtigen Plattform.','h1'=>'Sicherheit jenseits des Sichtbaren.','lead'=>'Eine geschützte Plattform, die Gegenüberwachung, Cybersicherheit, digitale Forensik und Datenschutztechnologie in einer einheitlichen Erfahrung verbindet.','section'=>'Mehrschichtige Sicherheitskompetenz','body'=>['NEXVARY verbindet Sicherheitsebenen, die häufig getrennt verwaltet werden: Endpunkt- und Netzwerkschutz, Verringerung technischer Exposition, Bewusstsein für Überwachungsrisiken, Datenschutztechnik und digitale Forensik, wenn Beweise erhalten und untersucht werden müssen. Ziel ist nicht, einfach mehr Werkzeuge anzubieten. Stattdessen entsteht ein klarer Ablauf von der Reduzierung der Angriffsfläche über Validierung und Untersuchung bis zu einer nachvollziehbaren Berichterstattung, die eine operative Entscheidung unterstützen kann.','Die Plattform trennt bewusst zwischen Informations- und Awareness-Funktionen, defensiver Software und Arbeiten, die eine professionelle Validierung benötigen. Besucher können Sicherheitsdienste prüfen, datenschutzorientierte Anwendungen erkunden, veröffentlichte Projekte ansehen oder NEXVARY wegen einer konkreten technischen Anforderung kontaktieren. Zentrale Inhalte, Navigation, Metadaten und strukturierte Informationen werden serverseitig ausgeliefert, sodass Suchmaschinen die öffentliche Website bereits vor der Ausführung von JavaScript vollständig erfassen können.'],'capabilities'=>['TSCM'=>'RF-Bewusstsein und technische Gegenüberwachung für sensible Umgebungen.','Cybersecurity'=>'Härtung, Bewertung, Verringerung der Angriffsfläche und Reaktion auf Vorfälle.','SafeScan'=>'Dateiprüfung im Browser ohne Speicherung und mit konsequenter Datenminimierung.','Audio Shield'=>'Datenschutzorientierter Audioschutz, Expositionsbewusstsein und defensive Abläufe.','Tower Guard'=>'Bewusstsein für Mobilfunkanomalien mit klaren Grenzen professioneller Validierung.','Digital Forensics'=>'Strukturierte Beweissicherung, Untersuchung und reproduzierbare Berichterstattung.']],
        'services'=>['title'=>'NEXVARY Sicherheitsdienste','description'=>'NEXVARY bietet TSCM, Cybersicherheit, Datenschutz, digitale Forensik, physische Sicherheitstechnik und Sicherheitsinformationen.','h1'=>'Interdisziplinärer technischer Schutz','lead'=>'Dienste zur Reduzierung digitaler und physischer Exposition mit klarer Trennung von Awareness, technischer Prüfung und professioneller Validierung.','body'=>['Die Dienste von NEXVARY sind darauf ausgerichtet, Risiken zu reduzieren, bevor daraus ein Vorfall entsteht. Eine Zusammenarbeit beginnt mit dem Verständnis der Umgebung und der wichtigen Werte. Anschließend werden mögliche Expositionen in Netzwerken, Endgeräten, drahtloser Kommunikation, physischen Räumen und betrieblichen Abläufen untersucht. Awareness-Werkzeuge werden bewusst von professioneller Validierung getrennt, damit ein Kunde versteht, was ein Software-Signal bedeutet und wann eine spezialisierte Inspektion oder formale Beweissicherung notwendig ist.','Cybersicherheitsarbeit konzentriert sich auf die Verringerung der Angriffsfläche, Härtung, Schwachstellenbewertung, Incident Response und Architektur. Technische Gegenüberwachung behandelt sensible Umgebungen, Funkfrequenz-Bewusstsein und strukturierte Inspektionen. Digitale Forensik legt Wert auf Beweiserhalt, reproduzierbare Analysen und belastbare Berichte. Physische Sicherheitstechnik verbindet Kameras, Zutrittskontrolle, Alarme, sichere Netzwerke und Sensoren zu einer koordinierten Schutzschicht.'],'cards'=>['TSCM & Counter-Surveillance'=>'Technische Inspektionen für Büros, Fahrzeuge, Räume, Geräte, Netzwerke und RF-Umgebungen.','Cybersecurity'=>'Bewertung, Härtung, Schwachstellenreduzierung, Incident Response und Sicherheitsarchitektur.','Digital Privacy'=>'Datenschutzorientierte Abläufe und Verringerung unnötiger Datenexposition.','Digital Forensics'=>'Strukturierte Beweisprüfung, Untersuchungsabläufe und belastbare Berichterstattung.','Physical Security Technology'=>'CCTV, Zutrittskontrolle, Alarmierung, sichere Netzwerke und Sensorintegration.','Security Intelligence'=>'Kuratierte Informationen zu Bedrohungen, Datenlecks und KI-Sicherheit für Entscheidungen.']],
        'apps'=>['title'=>'NEXVARY Sicherheitsanwendungen','description'=>'Entdecken Sie NEXVARY Anwendungen für Datenschutz, speicherfreie Prüfung, Bedrohungsinformationen, Mobilfunkbewusstsein und digitale Forensik.','h1'=>'Sicherheitsanwendungen auf einer Plattform','lead'=>'Defensive und datenschutzorientierte Anwendungen mit nützlichen Signalen, klaren Abläufen und kontrollierten Veröffentlichungen.','body'=>['Das NEXVARY-Anwendungsökosystem ist so strukturiert, dass Datenschutzwerkzeuge, Prüfprogramme, Informationsoberflächen und forensische Arbeitsabläufe nicht miteinander verschwimmen. Einige Werkzeuge laufen lokal im Browser, um unnötige Datenübertragung zu reduzieren. Andere liefern Analyse oder Kontext, damit ein Operator ein Signal verstehen kann, bevor professionelle Validierung erforderlich wird. Jede Anwendung soll klar erklären, was sie tut, welche Daten sie verarbeitet und wo ihre technischen Grenzen liegen.','SafeScan demonstriert den Ansatz ohne Speicherung, indem die primäre Prüfung im Browser bleibt. Andere Produkte konzentrieren sich auf Mobilfunkbewusstsein, Audioprivatsphäre, Sicherheitsinformationen oder reproduzierbare DFIR-Abläufe. Veröffentlichte Projekte und ihr Verfügbarkeitsstatus sind unter Projekte sichtbar. Downloads erscheinen nur, wenn ein Projekt ausdrücklich für die Verteilung freigegeben wurde und den für das jeweilige Produkt vorgesehenen Release-Prozess bestanden hat.'],'cards'=>['Audio Shield'=>'Datenschutzorientierter Audioschutz und Bewusstsein für technische Exposition.','Tower Guard'=>'Mobilfunkanomalie-Bewusstsein mit Hinweisen zur professionellen Validierung.','SafeScan'=>'Speicherfreie statische Browser-Prüfung mit optionaler Hash-Reputation.','Threat Intelligence'=>'Kuratierte Sicherheitsinformationen und Hinweise für defensive Entscheidungen.','AI Intelligence'=>'Fokus auf KI-Sicherheit, neue Technologien und zugehörige Risiken.','DFIR Lab'=>'Strukturierte digitale Forensik und Unterstützung bei Untersuchungen.'],'open'=>'SafeScan öffnen'],
        'safescan'=>['title'=>'SafeScan — Dateiprüfung Ohne Speicherung','description'=>'SafeScan prüft Dateien primär im Browser, ohne Dateiinhalte an NEXVARY hochzuladen, und bietet optional eine SHA-256-Reputationsabfrage.','h1'=>'SafeScan','lead'=>'Die primäre Prüfung läuft im Browser. Dateiinhalte werden nicht an NEXVARY hochgeladen; optional kann nur der SHA-256-Hash für eine Reputationsabfrage verwendet werden.','section'=>'Was passiert mit Ihrer Datei?','steps'=>[['Lokales Lesen','Der Browser liest Dateieigenschaften lokal für die primäre Prüfung.'],['SHA-256','Ein kryptografischer Fingerabdruck kann ohne Übertragung des Dateiinhalts berechnet werden.'],['Optionale Abfrage','Ist die Reputationsprüfung aktiv, wird nur der Hash an den Reputationsdienst übermittelt.']],'body'=>['SafeScan wurde nach dem Prinzip der Datenminimierung entwickelt. Statt eine vollständige Datei auf einen zentralen Server zu laden, nur um grundlegende Eigenschaften zu untersuchen, erfolgt die primäre Analyse soweit technisch möglich direkt im Browser. Dadurch sinkt die unnötige Exposition, und der Benutzer kann besser nachvollziehen, welche Daten lokal bleiben und welche technische Information eventuell an einen externen Reputationsdienst übermittelt wird. Das erste Browser-Signal wird bewusst nicht als formales Malware- oder Forensikurteil dargestellt.','Bei aktivierter Reputationsabfrage kann SafeScan einen SHA-256-Fingerabdruck berechnen und diesen als technischen Identifikator nutzen, ohne den ursprünglichen Dateiinhalten zu übertragen. Ein Reputationsergebnis ist ein zusätzliches Signal und keine Garantie dafür, dass eine Datei sicher oder schädlich ist. Sensible Materialien, Incident-Response-Beweise und forensische Fälle benötigen strengere Behandlung, Beweissicherung und professionelle Validierung außerhalb einer vorläufigen Browser-Prüfung.']],
        'about'=>['title'=>'Über NEXVARY Sicherheitstechnologie','description'=>'Erfahren Sie mehr über NEXVARY und den Ansatz für Cybersicherheit, technische Gegenüberwachung, digitale Forensik, Datenschutz und mehrschichtigen Schutz.','h1'=>'Sicherheitstechnologie für Risiken, die nicht sofort sichtbar sind.','lead'=>'NEXVARY verbindet Cybersicherheit, technische Gegenüberwachung, digitale Forensik und Datenschutztechnologie zu zusammenhängenden Schutzschichten.','body'=>['NEXVARY basiert auf der Erkenntnis, dass ein Sicherheitsrisiko nicht immer als offensichtlicher Angriff erscheint. Exposition kann in einer schwachen Konfiguration, einem nicht verwalteten Gerät, unnötiger Datenerhebung, einer ungeprüften sensiblen Umgebung oder unsachgemäß gesicherten digitalen Beweisen liegen. Deshalb verbindet die Plattform präventiven Schutz, technische Awareness, Datenschutztechnik und forensische Validierung, wenn ein Vorfall eine evidenzbasierte Untersuchung erfordert.','Software-Signale werden nicht als absolute Schlussfolgerungen dargestellt. Defensive Anwendungen können Probleme erkennen, klassifizieren, dokumentieren und priorisieren; bestimmte Situationen erfordern jedoch eine spezialisierte Inspektion, Feldausrüstung oder formale Verfahren zur Beweissicherung. Diese Trennung ist Teil des NEXVARY-Produktmodells und prägt die Darstellung von Diensten, Anwendungen, Projekten, Vertriebsstatus und Datenschutzanforderungen.'],'pillars'=>['Cybersecurity'=>'Angriffsfläche reduzieren und Systeme stärken, bevor Vorfälle entstehen.','Counter-Surveillance'=>'Technische Inspektion und Awareness für Umgebungen mit hohen Vertraulichkeitsanforderungen.','Digital Forensics'=>'Strukturierte Untersuchung und Beweisbehandlung mit reproduzierbaren Abläufen.','Privacy Technology'=>'Werkzeuge und Architektur zur Minimierung unnötiger Datenexposition.'],'channels'=>'Offizielle NEXVARY-Kanäle'],
        'contact'=>['title'=>'NEXVARY Sicherheitsteam Kontaktieren','description'=>'Kontaktieren Sie NEXVARY zu Cybersicherheit, TSCM, digitaler Forensik, Datenschutztechnologie, Partnerschaften und technischem Support.','h1'=>'Sagen Sie uns, wie wir helfen können.','lead'=>'Beschreiben Sie Ihr Anliegen klar, ohne Passwörter, geheime Schlüssel oder Zahlungsdaten zu übermitteln.','success'=>'Ihre Anfrage wurde erfolgreich empfangen. Vielen Dank für Ihre Kontaktaufnahme mit NEXVARY.','send'=>'Anfrage senden','fields'=>['name'=>'Vollständiger Name *','email'=>'E-Mail *','phone'=>'Telefon','company'=>'Unternehmen / Organisation','country'=>'Land','reason'=>'Grund der Kontaktaufnahme *','preferred'=>'Bevorzugter Kontaktweg *','message'=>'Ihre Nachricht *'],'reasons'=>['general'=>'Allgemeine Anfrage','cybersecurity'=>'Cybersicherheit','tscm'=>'Gegenüberwachung / TSCM','forensics'=>'Digitale Forensik','privacy'=>'Datenschutztechnologie','partnership'=>'Partnerschaft','support'=>'Support','other'=>'Sonstiges'],'phone_call'=>'Telefonanruf','body'=>['Nutzen Sie diese Seite für Fragen zu einem Sicherheitsdienst, einem technischen Projekt, einer Partnerschaft oder Support für NEXVARY-Produkte. Eine konkrete Beschreibung erleichtert die Zuordnung zum richtigen Ablauf. Senden Sie über das öffentliche Formular keine Passwörter, Einmalcodes, API-Geheimnisse, Zahlungskartendaten oder Kopien hochsensibler Materialien. Die erste Nachricht sollte nur die Informationen enthalten, die zum Verständnis der Anfrage erforderlich sind.','Bei einem aktiven Sicherheitsvorfall oder einem Thema mit digitalen Beweisen beschreiben Sie zunächst nur die allgemeine Umgebung und das Problem, damit vor dem Austausch sensibler Details ein geeigneter Kanal festgelegt werden kann. Für TSCM-Anfragen nennen Sie die Art des Büros, Raums, Fahrzeugs, Gerätesatzes oder der RF-Umgebung, ohne in der ersten Phase unnötige operative Informationen offenzulegen.']],
        'work'=>['title'=>'NEXVARY Projekte und Arbeiten','description'=>'Durchsuchen Sie veröffentlichte NEXVARY-Projekte mit klarem Status für Download, Showcase, Anfrage, interne Nutzung oder zukünftige Veröffentlichung.','h1'=>'Veröffentlichte Projekte mit klarem Verfügbarkeitsstatus','lead'=>'Jedes Projekt zeigt seinen tatsächlichen Status statt nicht verfügbarer Downloads oder toter Aktionen.','empty_title'=>'Noch keine veröffentlichten Projekte','empty_text'=>'Projekte erscheinen hier nach bestandener Release-Prüfung und einer ausdrücklichen Vertriebsrichtlinie.','view'=>'Projekt ansehen','all'=>'Alle Projekte','ask'=>'Zum Projekt anfragen','download'=>'Release herunterladen','request'=>'Zugriff anfragen','features'=>'Wichtige Funktionen','screens'=>'Projekt-Screenshots','body'=>['Der Bereich Projekte ist kein automatischer Download-Shop. Einige Projekte werden als Showcase veröffentlicht, andere sind nur auf Anfrage verfügbar, manche bleiben intern und weitere können als „demnächst“ erscheinen. Ein öffentlicher Download wird nur angezeigt, wenn die Vertriebsrichtlinie ihn ausdrücklich erlaubt. Dadurch bleibt der Verfügbarkeitsstatus korrekt und es entstehen keine Schaltflächen, die zu fehlenden Dateien, unzugänglichen Seiten oder unklaren Releases führen.','Die gleiche Struktur hilft Suchmaschinen, die Beziehung zwischen dem Projektkatalog und jeder veröffentlichten Detailseite zu verstehen. Interne Links verbinden den Katalog mit den einzelnen Projekten, während die Sitemap nur Oberflächen enthält, die für öffentliche Auffindbarkeit vorgesehen sind. Wer ein Projekt mit Zugriff auf Anfrage benötigt, kann die Kontaktseite nutzen, statt auf einen toten oder nicht autorisierten Download-Pfad zu stoßen.'],'show_body'=>['Diese Seite zeigt die offiziell veröffentlichten Informationen zum Projekt und seinen aktuellen Verfügbarkeitsstatus. Ein Projekt kann öffentlich herunterladbar, als Showcase veröffentlicht, auf Anfrage erhältlich, intern beschränkt oder als „demnächst“ geführt sein. Eine öffentliche Download-Aktion erscheint nur, wenn die Vertriebsrichtlinie dies ausdrücklich erlaubt und eine Release-Datei konfiguriert wurde.','Plattform, Version, Funktionen und Verfügbarkeit helfen dabei, Identität und beabsichtigte Verteilung des Projekts vor der Nutzung zu prüfen. Enthält ein öffentlicher Release Integritätsinformationen, sollten Version und Prüfsumme verifiziert werden. Interne oder eingeschränkte Projekte sollten nicht aus inoffiziellen Mirrors oder weiterverteilten Kopien außerhalb des kontrollierten NEXVARY-Kanals bezogen werden.'],'availability'=>'Die hier angezeigte Verfügbarkeit ist der aktuelle offizielle Vertriebsstatus dieses Projekts.'],
    ],

    'it' => [
        'name'=>'Italiano','dir'=>'ltr','og_locale'=>'it_IT','nav'=>['home'=>'Home','services'=>'Servizi','work'=>'Progetti','apps'=>'Applicazioni','about'=>'Chi siamo','contact'=>'Contatti','back'=>'Indietro'],'tagline'=>'Sicurezza oltre ciò che è visibile.',
        'home'=>['title'=>'NEXVARY — Sicurezza Oltre il Visibile','description'=>'NEXVARY unisce cybersecurity, contro-sorveglianza tecnica, informatica forense e tecnologie per la privacy in una piattaforma multilivello.','h1'=>'Sicurezza oltre ciò che è visibile.','lead'=>'Una piattaforma protetta che riunisce contro-sorveglianza, cybersecurity, informatica forense e tecnologie per la privacy in un’unica esperienza.','section'=>'Una capacità di sicurezza multilivello','body'=>['NEXVARY collega livelli di sicurezza che spesso vengono gestiti separatamente: difesa di endpoint e reti, riduzione dell’esposizione tecnica, consapevolezza dei rischi di sorveglianza, ingegneria della privacy e flussi di informatica forense quando le prove devono essere preservate e analizzate. L’obiettivo non è semplicemente aggiungere più strumenti, ma creare un percorso chiaro dalla riduzione della superficie di attacco alla verifica, all’indagine e infine a una reportistica in grado di sostenere una decisione operativa motivata.','La piattaforma distingue in modo intenzionale tra funzioni di consapevolezza, software difensivo e attività che richiedono validazione professionale. I visitatori possono consultare i servizi di sicurezza, esplorare applicazioni orientate alla privacy, vedere i progetti pubblicati o contattare NEXVARY per un’esigenza tecnica specifica. Contenuti essenziali, navigazione, metadati e informazioni strutturate vengono forniti dal server, così i crawler possono comprendere il sito pubblico prima dell’esecuzione di JavaScript.'],'capabilities'=>['TSCM'=>'Consapevolezza RF e contro-sorveglianza tecnica per ambienti sensibili.','Cybersecurity'=>'Hardening, valutazione, riduzione della superficie di attacco e risposta agli incidenti.','SafeScan'=>'Ispezione file nel browser senza archiviazione e con minimizzazione dei dati.','Audio Shield'=>'Protezione della privacy audio, consapevolezza dell’esposizione e flussi difensivi.','Tower Guard'=>'Consapevolezza delle anomalie cellulari con chiari limiti di validazione professionale.','Digital Forensics'=>'Gestione strutturata delle prove, indagine e reportistica ripetibile.']],
        'services'=>['title'=>'Servizi di Sicurezza NEXVARY','description'=>'I servizi NEXVARY coprono TSCM, cybersecurity, privacy, informatica forense, sicurezza fisica tecnologica e intelligence di sicurezza.','h1'=>'Protezione tecnica multidisciplinare','lead'=>'Servizi progettati per ridurre l’esposizione digitale e fisica, separando chiaramente consapevolezza, ispezione tecnica e validazione professionale.','body'=>['I servizi NEXVARY sono organizzati per ridurre il rischio prima che diventi un incidente. Un’attività inizia comprendendo l’ambiente e gli asset importanti, quindi valuta la possibile esposizione attraverso reti, endpoint, comunicazioni wireless, spazi fisici e processi operativi. Gli strumenti di consapevolezza vengono separati dalla validazione professionale, così il cliente può capire cosa significa un segnale software e quando sono necessari un’ispezione specialistica o un trattamento formale delle prove.','Il lavoro di cybersecurity si concentra su riduzione della superficie di attacco, hardening, revisione delle vulnerabilità, risposta agli incidenti e architettura. La contro-sorveglianza tecnica riguarda ambienti sensibili, consapevolezza delle radiofrequenze e ispezioni strutturate. L’informatica forense privilegia conservazione delle prove, analisi ripetibile e report difendibili. La sicurezza fisica collega telecamere, controllo accessi, allarmi, reti sicure e sensori in uno strato coordinato.'],'cards'=>['TSCM & Counter-Surveillance'=>'Ispezioni tecniche per uffici, veicoli, stanze, dispositivi, reti e ambienti RF.','Cybersecurity'=>'Valutazione, hardening, riduzione delle vulnerabilità, risposta agli incidenti e architettura.','Digital Privacy'=>'Flussi orientati alla privacy e riduzione dell’esposizione non necessaria dei dati.','Digital Forensics'=>'Analisi strutturata delle prove, indagini e reportistica difendibile.','Physical Security Technology'=>'CCTV, controllo accessi, allarmi, reti sicure e integrazione di sensori.','Security Intelligence'=>'Intelligence selezionata su minacce, violazioni e sicurezza AI per supportare le decisioni.']],
        'apps'=>['title'=>'Applicazioni di Sicurezza NEXVARY','description'=>'Scopri le applicazioni NEXVARY per privacy, ispezione senza archiviazione, intelligence delle minacce, consapevolezza cellulare e forense digitale.','h1'=>'Applicazioni di sicurezza, una piattaforma','lead'=>'Applicazioni difensive e orientate alla privacy con segnali utili, flussi chiari e percorsi di rilascio controllati.','body'=>['L’ecosistema di applicazioni NEXVARY è strutturato affinché strumenti per la privacy, utility di ispezione, superfici di intelligence e flussi forensi non si confondano tra loro. Alcuni strumenti operano localmente nel browser per ridurre trasferimenti di dati non necessari; altri forniscono analisi e contesto che aiutano l’operatore a comprendere un segnale prima di richiedere una validazione professionale. Ogni applicazione deve spiegare cosa fa, quali dati tratta e quali sono i suoi limiti tecnici.','SafeScan dimostra l’approccio senza archiviazione mantenendo l’ispezione primaria nel browser. Altri prodotti si concentrano su consapevolezza cellulare, privacy audio, intelligence di sicurezza o flussi DFIR ripetibili. I progetti pubblicati e il loro stato sono disponibili nella sezione Progetti. Il download compare solo quando un progetto è esplicitamente configurato per la distribuzione e ha superato il processo di rilascio previsto per quel prodotto.'],'cards'=>['Audio Shield'=>'Protezione della privacy audio e consapevolezza dell’esposizione tecnica.','Tower Guard'=>'Consapevolezza delle anomalie cellulari con indicazioni per la validazione professionale.','SafeScan'=>'Ispezione statica nel browser senza archiviazione con reputazione hash opzionale.','Threat Intelligence'=>'Intelligence di sicurezza selezionata e indicazioni per decisioni difensive.','AI Intelligence'=>'Focus su sicurezza AI, tecnologie emergenti e rischi associati.','DFIR Lab'=>'Flussi strutturati di informatica forense e supporto alle indagini.'],'open'=>'Apri SafeScan'],
        'safescan'=>['title'=>'SafeScan — Ispezione File Senza Archiviazione','description'=>'SafeScan esegue l’ispezione primaria nel browser senza caricare i contenuti dei file su NEXVARY e offre una verifica opzionale della reputazione SHA-256.','h1'=>'SafeScan','lead'=>'L’ispezione primaria avviene nel browser. Il contenuto del file non viene caricato su NEXVARY; per la reputazione opzionale può essere usato solo l’hash SHA-256.','section'=>'Cosa succede al tuo file?','steps'=>[['Lettura locale','Il browser legge localmente le caratteristiche del file per l’ispezione primaria.'],['SHA-256','È possibile calcolare un’impronta crittografica senza inviare il contenuto del file.'],['Verifica opzionale','Se la reputazione è attiva, al servizio viene inviato soltanto l’hash.']],'body'=>['SafeScan è progettato secondo il principio della minimizzazione dei dati. Invece di caricare un file completo su un server centrale soltanto per esaminarne le caratteristiche di base, l’analisi primaria viene eseguita nel browser quando la piattaforma lo consente. Questo riduce l’esposizione non necessaria e rende più chiaro all’utente quali dati restano locali e quale informazione tecnica potrebbe essere condivisa con un servizio esterno di reputazione. Il segnale preliminare del browser non viene presentato come una conclusione formale di malware analysis o informatica forense.','Quando la verifica reputazionale è abilitata, SafeScan può calcolare l’impronta SHA-256 e usarla come identificatore tecnico senza trasmettere il contenuto originale del file. Il risultato della reputazione è un segnale aggiuntivo, non una garanzia che il file sia sicuro o dannoso. Materiale sensibile, prove di risposta agli incidenti o casi forensi richiedono gestione più rigorosa, preservazione delle prove e validazione specialistica oltre un controllo preliminare nel browser.']],
        'about'=>['title'=>'Chi è NEXVARY e la Sicurezza Tecnologica','description'=>'Scopri NEXVARY e il suo approccio a cybersecurity, contro-sorveglianza tecnica, informatica forense, privacy e protezione multilivello.','h1'=>'Tecnologia di sicurezza per ciò che non è immediatamente visibile.','lead'=>'NEXVARY collega cybersecurity, contro-sorveglianza tecnica, informatica forense e tecnologie per la privacy in livelli di protezione coordinati.','body'=>['NEXVARY nasce dall’idea che il rischio di sicurezza non si presenti sempre come un attacco evidente. L’esposizione può trovarsi in una configurazione debole, un dispositivo non gestito, una raccolta dati non necessaria, un ambiente sensibile non ispezionato tecnicamente o una prova digitale non preservata correttamente. Per questo la piattaforma collega protezione preventiva, consapevolezza tecnica, ingegneria della privacy e validazione forense quando un incidente richiede una revisione basata sulle prove.','I segnali software non vengono presentati come conclusioni assolute. Le applicazioni difensive possono aiutare a rilevare, classificare, documentare e dare priorità ai problemi, mentre alcune situazioni richiedono un’ispezione specialistica, apparecchiature sul campo o procedure formali di gestione delle prove. Questa distinzione fa parte del modello NEXVARY e influenza il modo in cui servizi, applicazioni, progetti, distribuzione e aspettative di privacy vengono comunicati.'],'pillars'=>['Cybersecurity'=>'Riduzione della superficie di attacco e rafforzamento dei sistemi prima degli incidenti.','Counter-Surveillance'=>'Ispezione tecnica e consapevolezza per ambienti dove la riservatezza è fondamentale.','Digital Forensics'=>'Indagine strutturata e gestione delle prove con flussi ripetibili.','Privacy Technology'=>'Strumenti e architettura per minimizzare l’esposizione non necessaria dei dati.'],'channels'=>'Canali ufficiali NEXVARY'],
        'contact'=>['title'=>'Contatta il Team di Sicurezza NEXVARY','description'=>'Contatta NEXVARY per cybersecurity, TSCM, informatica forense, tecnologie per la privacy, partnership e supporto tecnico.','h1'=>'Dicci come possiamo aiutarti.','lead'=>'Descrivi chiaramente la richiesta senza condividere password, chiavi segrete o dati di pagamento.','success'=>'La richiesta è stata ricevuta correttamente. Grazie per aver contattato NEXVARY.','send'=>'Invia richiesta','fields'=>['name'=>'Nome completo *','email'=>'Email *','phone'=>'Telefono','company'=>'Azienda / Organizzazione','country'=>'Paese','reason'=>'Motivo del contatto *','preferred'=>'Metodo di contatto preferito *','message'=>'Messaggio *'],'reasons'=>['general'=>'Richiesta generale','cybersecurity'=>'Cybersecurity','tscm'=>'Contro-sorveglianza / TSCM','forensics'=>'Informatica forense','privacy'=>'Tecnologia privacy','partnership'=>'Partnership','support'=>'Supporto','other'=>'Altro'],'phone_call'=>'Telefonata','body'=>['Usa questa pagina per domande su un servizio di sicurezza, un progetto tecnico, una partnership o il supporto ai prodotti NEXVARY. Una descrizione precisa facilita l’instradamento della richiesta nel flusso appropriato. Non inviare tramite il modulo pubblico password, codici monouso, segreti API, dati di carte di pagamento o copie di materiale altamente sensibile. Il primo messaggio deve contenere solo le informazioni necessarie per comprendere la natura della richiesta.','Per un incidente di sicurezza attivo o una questione relativa a prove digitali, descrivi inizialmente l’ambiente generale e il problema, così potrà essere stabilito un canale adeguato prima dello scambio di dettagli sensibili. Per richieste TSCM indica il tipo di ufficio, stanza, veicolo, insieme di dispositivi o ambiente RF da valutare senza esporre informazioni operative non necessarie nella fase iniziale.']],
        'work'=>['title'=>'Progetti e Lavori NEXVARY','description'=>'Esplora i progetti NEXVARY pubblicati con stato chiaro per download, vetrina, accesso su richiesta, uso interno o prossima disponibilità.','h1'=>'Progetti pubblicati con disponibilità chiara','lead'=>'Ogni progetto dichiara lo stato reale invece di mostrare download non disponibili o azioni inattive.','empty_title'=>'Nessun progetto pubblicato al momento','empty_text'=>'I progetti appariranno qui dopo il superamento del gate di rilascio e l’assegnazione di una politica di distribuzione esplicita.','view'=>'Visualizza progetto','all'=>'Tutti i progetti','ask'=>'Chiedi informazioni','download'=>'Scarica release','request'=>'Richiedi accesso','features'=>'Funzionalità principali','screens'=>'Screenshot del progetto','body'=>['La sezione Progetti non è un negozio di download automatico. Alcuni progetti vengono pubblicati come vetrina, altri sono disponibili soltanto su richiesta, alcuni rimangono interni e altri possono essere indicati come prossimamente disponibili. Il download pubblico compare solo quando la politica di distribuzione lo consente esplicitamente. Questo mantiene accurato lo stato di disponibilità ed evita pulsanti che portano a file mancanti, pagine inaccessibili o release ambigue.','La stessa struttura aiuta i crawler a comprendere la relazione tra il catalogo e ogni pagina di progetto pubblicata. I collegamenti interni connettono il catalogo ai singoli record, mentre la sitemap comprende soltanto le superfici destinate alla scoperta pubblica. Chi necessita di un progetto disponibile su richiesta può utilizzare la pagina Contatti invece di incontrare un percorso di download inattivo o non autorizzato.'],'show_body'=>['Questa pagina presenta le informazioni pubblicate ufficialmente sul progetto e il suo stato attuale. Un progetto può essere scaricabile pubblicamente, mostrato come vetrina, disponibile su richiesta, limitato all’uso interno o indicato come prossimamente disponibile. Il download pubblico viene esposto soltanto quando la politica di distribuzione lo permette e un file di release è stato configurato.','Piattaforma, versione, funzionalità e disponibilità aiutano a verificare l’identità del progetto e la distribuzione prevista prima dell’uso. Quando una release pubblica include informazioni di integrità, è opportuno verificare versione e checksum pubblicati. Progetti interni o limitati non dovrebbero essere ottenuti da mirror non ufficiali o copie ridistribuite fuori dal percorso NEXVARY controllato.'],'availability'=>'La disponibilità mostrata qui rappresenta lo stato ufficiale corrente di distribuzione del progetto.'],
    ],

    'es' => [
        'name'=>'Español','dir'=>'ltr','og_locale'=>'es_ES','nav'=>['home'=>'Inicio','services'=>'Servicios','work'=>'Proyectos','apps'=>'Aplicaciones','about'=>'Nosotros','contact'=>'Contacto','back'=>'Volver'],'tagline'=>'Seguridad más allá de lo visible.',
        'home'=>['title'=>'NEXVARY — Seguridad Más Allá de lo Visible','description'=>'NEXVARY integra ciberseguridad, contravigilancia técnica, análisis forense digital y tecnología de privacidad en una plataforma multicapa.','h1'=>'Seguridad más allá de lo visible.','lead'=>'Una plataforma protegida que unifica contravigilancia, ciberseguridad, análisis forense digital y tecnologías de privacidad en una sola experiencia.','section'=>'Capacidad de seguridad multicapa','body'=>['NEXVARY conecta capas de seguridad que a menudo se gestionan por separado: defensa de endpoints y redes, reducción de exposición técnica, conciencia frente a riesgos de vigilancia, ingeniería de privacidad y flujos de análisis forense digital cuando es necesario preservar y revisar evidencias. El objetivo no es simplemente añadir más herramientas. Buscamos crear un recorrido claro desde la reducción de la superficie de ataque, pasando por la validación y la investigación, hasta una documentación capaz de respaldar una decisión operativa fundamentada.','La plataforma diferencia deliberadamente entre funciones de concienciación, software defensivo y trabajos que requieren validación profesional. Los visitantes pueden revisar los servicios de seguridad, explorar aplicaciones centradas en la privacidad, consultar proyectos publicados o contactar con NEXVARY para una necesidad técnica concreta. El contenido esencial, la navegación, los metadatos y la información estructurada se entregan desde el servidor, de modo que los rastreadores pueden comprender el sitio público antes de ejecutar JavaScript.'],'capabilities'=>['TSCM'=>'Conciencia RF y contravigilancia técnica para entornos sensibles.','Cybersecurity'=>'Endurecimiento, evaluación, reducción de superficie de ataque y respuesta a incidentes.','SafeScan'=>'Inspección de archivos en el navegador sin almacenamiento y con minimización de datos.','Audio Shield'=>'Protección de privacidad de audio, conciencia de exposición y flujos defensivos.','Tower Guard'=>'Conciencia de anomalías celulares con límites claros de validación profesional.','Digital Forensics'=>'Gestión estructurada de evidencias, investigación e informes repetibles.']],
        'services'=>['title'=>'Servicios de Seguridad NEXVARY','description'=>'Los servicios NEXVARY cubren TSCM, ciberseguridad, privacidad, análisis forense digital, tecnología de seguridad física e inteligencia de seguridad.','h1'=>'Protección técnica multidisciplinar','lead'=>'Servicios diseñados para reducir la exposición digital y física separando claramente concienciación, inspección técnica y validación profesional.','body'=>['Los servicios NEXVARY se organizan para reducir el riesgo antes de que se convierta en un incidente. El trabajo comienza comprendiendo el entorno y los activos importantes, y después revisa la posible exposición en redes, endpoints, comunicaciones inalámbricas, espacios físicos y procesos operativos. Las herramientas de concienciación se separan de la validación profesional para que el cliente entienda qué significa una señal de software y cuándo hace falta una inspección especializada o un manejo formal de evidencias.','El trabajo de ciberseguridad se centra en reducir la superficie de ataque, endurecer configuraciones, revisar vulnerabilidades, responder a incidentes y diseñar arquitectura. La contravigilancia técnica aborda entornos sensibles, conciencia de radiofrecuencia e inspecciones estructuradas. El análisis forense digital prioriza la preservación de evidencias, el análisis repetible y los informes defendibles. La seguridad física integra cámaras, control de acceso, alarmas, redes seguras y sensores en una capa coordinada.'],'cards'=>['TSCM & Counter-Surveillance'=>'Inspecciones técnicas para oficinas, vehículos, habitaciones, dispositivos, redes y entornos RF.','Cybersecurity'=>'Evaluación, endurecimiento, reducción de vulnerabilidades, respuesta a incidentes y arquitectura.','Digital Privacy'=>'Flujos centrados en privacidad y reducción de exposición innecesaria de datos.','Digital Forensics'=>'Revisión estructurada de evidencias, investigación e informes defendibles.','Physical Security Technology'=>'CCTV, control de acceso, alarmas, redes seguras e integración de sensores.','Security Intelligence'=>'Inteligencia seleccionada sobre amenazas, brechas y seguridad de IA para apoyar decisiones.']],
        'apps'=>['title'=>'Aplicaciones de Seguridad NEXVARY','description'=>'Explora aplicaciones NEXVARY para privacidad, inspección sin almacenamiento, inteligencia de amenazas, conciencia celular y análisis forense digital.','h1'=>'Aplicaciones de seguridad en una plataforma','lead'=>'Aplicaciones defensivas y centradas en privacidad con señales útiles, flujos claros y rutas de publicación controladas.','body'=>['El ecosistema de aplicaciones NEXVARY está estructurado para que las herramientas de privacidad, las utilidades de inspección, las superficies de inteligencia y los flujos forenses no se mezclen entre sí. Algunas herramientas funcionan localmente en el navegador para reducir transferencias de datos innecesarias; otras aportan análisis o contexto para ayudar al operador a comprender una señal antes de solicitar validación profesional. Cada aplicación debe explicar qué hace, qué datos maneja y dónde están sus límites técnicos.','SafeScan demuestra el enfoque sin almacenamiento manteniendo la inspección principal dentro del navegador. Otros productos se centran en conciencia celular, privacidad de audio, inteligencia de seguridad o flujos DFIR repetibles. Los proyectos publicados y su estado de disponibilidad pueden consultarse en Proyectos. Las descargas solo aparecen cuando un proyecto se configura expresamente para distribución y ha superado el proceso de publicación correspondiente a ese producto.'],'cards'=>['Audio Shield'=>'Protección de privacidad de audio y conciencia de exposición técnica.','Tower Guard'=>'Conciencia de anomalías celulares con orientación para validación profesional.','SafeScan'=>'Inspección estática en navegador sin almacenamiento y reputación hash opcional.','Threat Intelligence'=>'Inteligencia de seguridad seleccionada y orientación para decisiones defensivas.','AI Intelligence'=>'Enfoque en seguridad de IA, tecnologías emergentes y riesgos asociados.','DFIR Lab'=>'Flujos estructurados de análisis forense digital y apoyo a investigaciones.'],'open'=>'Abrir SafeScan'],
        'safescan'=>['title'=>'SafeScan — Inspección de Archivos Sin Almacenamiento','description'=>'SafeScan realiza la inspección principal en el navegador sin subir el contenido del archivo a NEXVARY y ofrece una consulta de reputación SHA-256 opcional.','h1'=>'SafeScan','lead'=>'La inspección principal se ejecuta en el navegador. El contenido del archivo no se sube a NEXVARY; solo puede utilizarse el hash SHA-256 para una consulta opcional.','section'=>'¿Qué ocurre con tu archivo?','steps'=>[['Lectura local','El navegador lee localmente las características del archivo para la inspección principal.'],['SHA-256','Puede calcularse una huella criptográfica sin enviar el contenido del archivo.'],['Consulta opcional','Si se activa la reputación, únicamente se envía el hash al servicio correspondiente.']],'body'=>['SafeScan se diseña alrededor del principio de minimización de datos. En lugar de subir un archivo completo a un servidor central solo para inspeccionar características básicas, el análisis principal se realiza dentro del navegador siempre que la plataforma lo permite. Esto reduce la exposición innecesaria y permite al usuario comprender mejor qué datos permanecen localmente y qué información técnica podría compartirse con un servicio externo de reputación. La señal preliminar del navegador no se presenta como una conclusión formal de malware o análisis forense.','Cuando se habilita la consulta de reputación, SafeScan puede calcular una huella SHA-256 y utilizarla como identificador técnico sin transmitir el contenido original del archivo. El resultado de reputación es una señal adicional y no garantiza que un archivo sea seguro o malicioso. Material sensible, evidencias de respuesta a incidentes o casos forenses requieren un tratamiento más estricto, preservación de evidencias y validación especializada más allá de una inspección preliminar en el navegador.']],
        'about'=>['title'=>'Acerca de la Tecnología de Seguridad NEXVARY','description'=>'Conoce NEXVARY y su enfoque de ciberseguridad, contravigilancia técnica, análisis forense digital, privacidad y protección por capas.','h1'=>'Tecnología de seguridad para riesgos que no son visibles de inmediato.','lead'=>'NEXVARY combina ciberseguridad, contravigilancia técnica, análisis forense digital y tecnologías de privacidad en capas de protección conectadas.','body'=>['NEXVARY parte de la idea de que un riesgo de seguridad no siempre aparece como un ataque evidente. La exposición puede estar en una configuración débil, un dispositivo sin gestión, una recopilación innecesaria de datos, un entorno sensible que no ha sido inspeccionado técnicamente o una evidencia digital que no se preservó correctamente. Por ello la plataforma conecta protección preventiva, conciencia técnica, ingeniería de privacidad y validación forense cuando un incidente necesita una revisión basada en evidencias.','Las señales de software no se presentan como conclusiones absolutas. Las aplicaciones defensivas pueden ayudar a detectar, clasificar, documentar y priorizar problemas, mientras que algunas situaciones requieren una inspección especializada, equipos de campo o procedimientos formales de manejo de evidencias. Esta distinción forma parte del modelo de NEXVARY y se refleja en cómo se comunican servicios, aplicaciones, proyectos, estados de distribución y expectativas de privacidad.'],'pillars'=>['Cybersecurity'=>'Reducir la superficie de ataque y reforzar sistemas antes de que ocurran incidentes.','Counter-Surveillance'=>'Inspección técnica y concienciación para entornos donde la confidencialidad es esencial.','Digital Forensics'=>'Investigación estructurada y manejo de evidencias con flujos repetibles.','Privacy Technology'=>'Herramientas y arquitectura que minimizan la exposición innecesaria de datos.'],'channels'=>'Canales oficiales de NEXVARY'],
        'contact'=>['title'=>'Contactar con el Equipo de Seguridad NEXVARY','description'=>'Contacta con NEXVARY sobre ciberseguridad, TSCM, análisis forense digital, privacidad, colaboraciones y soporte técnico.','h1'=>'Cuéntanos cómo podemos ayudarte.','lead'=>'Describe tu solicitud con claridad sin compartir contraseñas, claves secretas ni datos de pago.','success'=>'Tu solicitud se recibió correctamente. Gracias por contactar con NEXVARY.','send'=>'Enviar solicitud','fields'=>['name'=>'Nombre completo *','email'=>'Correo electrónico *','phone'=>'Teléfono','company'=>'Empresa / Organización','country'=>'País','reason'=>'Motivo del contacto *','preferred'=>'Método de contacto preferido *','message'=>'Tu mensaje *'],'reasons'=>['general'=>'Consulta general','cybersecurity'=>'Ciberseguridad','tscm'=>'Contravigilancia / TSCM','forensics'=>'Análisis forense digital','privacy'=>'Tecnología de privacidad','partnership'=>'Colaboración','support'=>'Soporte','other'=>'Otro'],'phone_call'=>'Llamada telefónica','body'=>['Utiliza esta página para preguntas sobre un servicio de seguridad, un proyecto técnico, una colaboración o soporte relacionado con productos NEXVARY. Una descripción concreta ayuda a dirigir la solicitud al flujo adecuado. No envíes mediante el formulario público contraseñas, códigos de un solo uso, secretos de API, datos de tarjetas ni copias de material altamente sensible. El primer mensaje debe incluir únicamente la información necesaria para entender la naturaleza de la solicitud.','Para un incidente de seguridad activo o un asunto de evidencia digital, describe primero el entorno general y el problema para establecer un canal adecuado antes de intercambiar detalles sensibles. En solicitudes TSCM indica el tipo de oficina, sala, vehículo, conjunto de dispositivos o entorno RF que debe evaluarse sin revelar información operativa innecesaria durante el primer contacto.']],
        'work'=>['title'=>'Proyectos y Trabajos NEXVARY','description'=>'Consulta proyectos NEXVARY publicados con estado claro para descarga, presentación, acceso por solicitud, uso interno o próxima disponibilidad.','h1'=>'Proyectos publicados con disponibilidad clara','lead'=>'Cada proyecto muestra su estado real en lugar de descargas no disponibles o acciones inactivas.','empty_title'=>'Todavía no hay proyectos publicados','empty_text'=>'Los proyectos aparecerán aquí después de superar el control de publicación y recibir una política de distribución explícita.','view'=>'Ver proyecto','all'=>'Todos los proyectos','ask'=>'Preguntar por el proyecto','download'=>'Descargar versión','request'=>'Solicitar acceso','features'=>'Funciones principales','screens'=>'Capturas del proyecto','body'=>['La sección Proyectos no funciona como una tienda automática de descargas. Algunos proyectos se publican como presentación, otros solo están disponibles mediante solicitud, algunos permanecen internos y otros pueden aparecer como próximamente disponibles. Una descarga pública se muestra únicamente cuando la política de distribución la permite expresamente. Esto mantiene exacto el estado de disponibilidad y evita botones que conduzcan a archivos inexistentes, páginas inaccesibles o versiones ambiguas.','La misma estructura ayuda a los rastreadores a comprender la relación entre el catálogo y cada página de proyecto publicada. Los enlaces internos conectan el catálogo con los registros individuales, mientras que el sitemap contiene solo superficies destinadas al descubrimiento público. Quien necesite un proyecto disponible bajo solicitud puede utilizar la página de contacto en lugar de encontrarse con una ruta de descarga inactiva o no autorizada.'],'show_body'=>['Esta página presenta la información publicada oficialmente sobre el proyecto y su disponibilidad actual. Un proyecto puede ser descargable públicamente, mostrarse como presentación, estar disponible bajo solicitud, quedar restringido a uso interno o aparecer como próximo. La descarga pública solo se expone cuando la política la permite y existe un archivo de versión configurado para entrega.','La plataforma, versión, funciones y disponibilidad ayudan a verificar la identidad del proyecto y su distribución prevista antes de utilizarlo. Cuando una versión pública incluye información de integridad, conviene comprobar la versión y el checksum publicados. Los proyectos internos o restringidos no deberían obtenerse desde mirrors no oficiales ni copias redistribuidas fuera del canal controlado de NEXVARY.'],'availability'=>'La disponibilidad mostrada aquí es el estado oficial actual de distribución de este proyecto.'],
    ],
];
